      'fonts.badge_beta': '\u0411\u0435\u0442\u0430',
      'fonts.convert_intro': '\u041F\u0440\u0430\u0446\u044E\u0454 \u0443 \u0446\u0456\u0439 \u0432\u043A\u043B\u0430\u0434\u0446\u0456 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u2014 \u043D\u0430 \u0432\u0430\u0448\u043E\u043C\u0443 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0456 \u0430\u0431\u043E \u043A\u043E\u043C\u043F\u2019\u044E\u0442\u0435\u0440\u0456, \u0430 \u043D\u0435 \u043D\u0430 \u0440\u0456\u0434\u0435\u0440\u0456 \u2014 \u0456 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0443\u0454 \u0433\u043E\u0442\u043E\u0432\u0438\u0439 \u0444\u0430\u0439\u043B. \u0416\u043E\u0434\u043D\u043E\u0433\u043E \u043E\u043A\u0440\u0435\u043C\u043E\u0433\u043E \u0434\u043E\u0434\u0430\u0442\u043A\u0430, \u0436\u043E\u0434\u043D\u0438\u0445 \u0441\u043A\u0440\u0438\u043F\u0442\u0456\u0432 \u043D\u0430 \u041A. \u041E\u0431\u0435\u0440\u0456\u0442\u044C \u043F\u0430\u043F\u043A\u0443 \u0437 \u0444\u0430\u0439\u043B\u0430\u043C\u0438 \u043D\u0430\u0447\u0435\u0440\u0442\u0430\u043D\u044C \u0448\u0440\u0438\u0444\u0442\u0443 (TTF/OTF) \u2014 Regular \u0442\u0430, \u0437\u0430 \u0431\u0430\u0436\u0430\u043D\u043D\u044F\u043C, \u0441\u043F\u0440\u0430\u0432\u0436\u043D\u0456 \u0444\u0430\u0439\u043B\u0438 Bold/Italic/Bold\u00A0Italic (\u043D\u0435 \u0456\u043C\u0456\u0442\u0430\u0446\u0456\u044F) \u2014 \u0432\u043E\u043D\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u0437\u0456\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442\u044C\u0441\u044F \u0437\u0430 \u0456\u043C\u2019\u044F\u043C \u0444\u0430\u0439\u043B\u0456\u0432 \u0456 \u043E\u0431\u2019\u0454\u0434\u043D\u0443\u044E\u0442\u044C\u0441\u044F \u0432 \u043E\u0434\u0438\u043D \u043C\u0443\u043B\u044C\u0442\u0438\u0441\u0442\u0438\u043B\u044C\u043E\u0432\u0438\u0439 .cpfont, \u0437 \u044F\u043A\u043E\u0433\u043E \u0440\u0456\u0434\u0435\u0440 \u0441\u0430\u043C \u043E\u0431\u0438\u0440\u0430\u0454 \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0438\u0439 \u0441\u0442\u0438\u043B\u044C. \u041A\u0435\u0440\u043D\u0456\u043D\u0433\u0443/\u043B\u0456\u0433\u0430\u0442\u0443\u0440 \u0443 \u043F\u043E\u0442\u043E\u0447\u043D\u043E\u043C\u0443 \u0440\u0435\u0436\u0438\u043C\u0456 \u043D\u0435\u043C\u0430\u0454 (\u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0438\u0439 \u0440\u043E\u0437\u0431\u0456\u0440 \u0442\u0430\u0431\u043B\u0438\u0446\u044C GPOS/GSUB, \u043F\u043E\u0437\u0430 \u043C\u0435\u0436\u0430\u043C\u0438 \u0446\u044C\u043E\u0433\u043E \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0430).',
