      'fonts.range_comprehensive': '\u041F\u043E\u0432\u043D\u0438\u0439 \u043D\u0430\u0431\u0456\u0440 (\u043B\u0430\u0442\u0438\u043D\u0438\u0446\u044F/\u043A\u0438\u0440\u0438\u043B\u0438\u0446\u044F/\u0433\u0440\u0435\u0446\u044C\u043A\u0430/\u0432\u0456\u0440\u043C\u0435\u043D\u0441\u044C\u043A\u0430/\u0456\u0432\u0440\u0438\u0442/\u0430\u0440\u0430\u0431\u0441\u044C\u043A\u0430/\u0434\u0435\u0432\u0430\u043D\u0430\u0433\u0430\u0440\u0456/\u0442\u0430\u0439\u0441\u044C\u043A\u0430/\u0433\u0440\u0443\u0437\u0438\u043D\u0441\u044C\u043A\u0430/CJK/\u0445\u0430\u043D\u0433\u0438\u043B\u044C/\u043A\u0430\u043D\u0430/\u0441\u0438\u043C\u0432\u043E\u043B\u0438)',
      'fonts.custom_ranges_label': '\u0412\u043B\u0430\u0441\u043D\u0456 \u0433\u043B\u0456\u0444\u0438, \u0434\u0456\u0430\u043F\u0430\u0437\u043E\u043D\u0438 Unicode',
      'fonts.custom_ranges_note': '(\u043D\u0435\u043E\u0431\u043E\u0432\u2019\u044F\u0437\u043A\u043E\u0432\u043E, \u0447\u0435\u0440\u0435\u0437 \u043A\u043E\u043C\u0443 \u2014 \u0434\u043E\u0434\u0430\u044E\u0442\u044C\u0441\u044F \u0434\u043E \u0432\u0438\u0431\u0440\u0430\u043D\u043E\u0433\u043E \u0432\u0438\u0449\u0435 \u0434\u0456\u0430\u043F\u0430\u0437\u043E\u043D\u0443)',
      'fonts.convert_upload_btn': '\u041A\u043E\u043D\u0432\u0435\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0439 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0438\u0442\u0438',
      'fonts.convert_hint': '\u00AB\u041F\u043E\u0432\u043D\u0438\u0439 \u043D\u0430\u0431\u0456\u0440\u00BB \u0437\u0430\u043F\u0438\u0442\u0443\u0454 \u0432\u0435\u043B\u0438\u043A\u0438\u0439 \u0434\u0456\u0430\u043F\u0430\u0437\u043E\u043D \u043F\u0438\u0441\u0435\u043C\u043D\u043E\u0441\u0442\u0435\u0439 \u0442\u0430 \u0441\u0438\u043C\u0432\u043E\u043B\u044C\u043D\u0438\u0445 \u0431\u043B\u043E\u043A\u0456\u0432, \u0430\u043B\u0435 \u0440\u0430\u0441\u0442\u0440\u0438\u0437\u043E\u0432\u0443\u044E\u0442\u044C\u0441\u044F \u043B\u0438\u0448\u0435 \u0442\u0456 \u0433\u043B\u0456\u0444\u0438, \u044F\u043A\u0456 \u0434\u0456\u0439\u0441\u043D\u043E \u0454 \u0443 \u0448\u0440\u0438\u0444\u0442\u0456 \u2014 \u043B\u0430\u0442\u0438\u043D\u0438\u0446\u044F/\u043A\u0438\u0440\u0438\u043B\u0438\u0446\u044F \u0437\u0430\u043B\u0438\u0448\u0430\u0454\u0442\u044C\u0441\u044F \u0448\u0432\u0438\u0434\u043A\u043E\u044E, \u0431\u043E \u0432\u0441\u0435 \u0456\u043D\u0448\u0435 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0454\u0442\u044C\u0441\u044F \u043F\u0456\u0441\u043B\u044F \u0448\u0432\u0438\u0434\u043A\u043E\u0457 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0438 \u043D\u0430\u044F\u0432\u043D\u043E\u0441\u0442\u0456. \u0428\u0440\u0438\u0444\u0442\u0438 \u0437 \u0440\u0435\u0430\u043B\u044C\u043D\u0438\u043C \u043F\u043E\u043A\u0440\u0438\u0442\u0442\u044F\u043C CJK/\u0445\u0430\u043D\u0433\u0438\u043B\u044F \u043C\u043E\u0436\u0443\u0442\u044C \u0437\u0430\u0439\u043D\u044F\u0442\u0438 \u0447\u0430\u0441 (\u0442\u0438\u0441\u044F\u0447\u0456 \u0433\u043B\u0456\u0444\u0456\u0432 \u043D\u0430 \u0441\u0442\u0438\u043B\u044C) \u2014 \u0437\u0430\u043B\u0438\u0448\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430 \u0446\u0456\u0439 \u0441\u0442\u043E\u0440\u0456\u043D\u0446\u0456 \u0434\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0443. \u041F\u043E\u0442\u0440\u0456\u0431\u0435\u043D \u0434\u043E\u0441\u0442\u0430\u0442\u043D\u044C\u043E \u0441\u0443\u0447\u0430\u0441\u043D\u0438\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 (\u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u044E\u0442\u044C\u0441\u044F FontFace \u0442\u0430 Canvas API). \u041F\u0440\u0430\u043A\u0442\u0438\u0447\u043D\u043E \u0431\u0435\u0437 \u043E\u0431\u043C\u0435\u0436\u0435\u043D\u043D\u044F \u0440\u043E\u0437\u043C\u0456\u0440\u0443, \u043D\u0430 \u0432\u0456\u0434\u043C\u0456\u043D\u0443 \u0432\u0456\u0434 \u043A\u043E\u043D\u0432\u0435\u0440\u0442\u0430\u0446\u0456\u0457 \u043D\u0430 \u043F\u0440\u0438\u0441\u0442\u0440\u043E\u0457 \u2014 \u0441\u043F\u0440\u0430\u0432\u0436\u043D\u0456 \u00AB\u0434\u0438\u0437\u0430\u0439\u043D\u0435\u0440\u0441\u044C\u043A\u0456\u00BB \u0448\u0440\u0438\u0444\u0442\u0438 (Bookerly, Amazon Ember, Literata \u0442\u043E\u0449\u043E) \u043F\u0440\u0430\u0446\u044E\u044E\u0442\u044C \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E. \u041A\u043E\u043D\u0432\u0435\u0440\u0442\u0443\u0454 \u0442\u0430 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0443\u0454 \u043E\u0434\u0438\u043D .cpfont \u043D\u0430 \u043A\u043E\u0436\u0435\u043D \u0440\u043E\u0437\u043C\u0456\u0440 (12/14/16/18pt \u043F\u043B\u044E\u0441 \u0442\u0435, \u0449\u043E \u0432\u0438 \u0434\u043E\u0434\u0430\u043B\u0438 \u0432\u0438\u0449\u0435) \u2014 \u043A\u043E\u0436\u043D\u0435 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043D\u044F \u043F\u043E \u0447\u0435\u0440\u0437\u0456, \u0442\u043E\u043C\u0443 \u0437 \u043A\u0456\u043B\u044C\u043A\u043E\u043C\u0430 \u0440\u043E\u0437\u043C\u0456\u0440\u0430\u043C\u0438 \u0446\u0435 \u0437\u0430\u0439\u043C\u0435 \u0447\u0430\u0441. \u0412\u043B\u0430\u0441\u043D\u0456 \u0434\u0456\u0430\u043F\u0430\u0437\u043E\u043D\u0438 \u2014 \u043E\u0434\u0438\u043D\u0430 \u043A\u043E\u0434\u043E\u0432\u0430 \u0442\u043E\u0447\u043A\u0430 \u0430\u0431\u043E \u0434\u0456\u0430\u043F\u0430\u0437\u043E\u043D \u0432\u0438\u0433\u043B\u044F\u0434\u0443 first-last, \u0437 \u043F\u0440\u0435\u0444\u0456\u043A\u0441\u043E\u043C 0x/U+ \u0430\u0431\u043E \u0431\u0435\u0437 \u043D\u044C\u043E\u0433\u043E.',
